use v5.42;
use strict;
use warnings;
use JSON::PP ();
use File::Basename 'dirname';
use Time::HiRes qw(clock_gettime CLOCK_MONOTONIC);
use Digest::SHA 'sha256_hex';
use Cwd 'abs_path';
use File::Temp 'tempfile';
use IPC::Open3;
@ARGV == 4 or die "usage: capture-yield-check.pl BEFORE AFTER WORKER METADATA\n";
my ($old, $binary, $worker, $metadata_path) = @ARGV;
sub contents ($path) {
	open my $in, '<', $path or die $!;
	my $text = do {local $/; <$in>};
	close $in or die $!;
	return $text;
}
sub capture (@command) {
	my ($errors) = tempfile(UNLINK => 1);
	my ($input, $in);
	my $pid = open3($input, $in, '>&' . fileno($errors), @command);
	close $input or die $!;
	my $text = do {local $/; <$in>};
	close $in or die $!;
	waitpid($pid, 0) == $pid or die $!;
	my $status = $?;
	seek $errors, 0, 0 or die $!;
	my $diagnostics = do {local $/; <$errors>};
	!$status && !length($diagnostics) or die "command failed ($status): @command\n$diagnostics";
	return $text;
}
my $revision = capture('git', 'rev-parse', 'HEAD'); chomp $revision;
for my $key (qw(PERL5OPT PERL5LIB PERLLIB PERL_UNICODE PERL_HASH_SEED PERL_PERTURB_KEYS PERLIO)) { delete $ENV{$key} }
local $ENV{LC_ALL} = 'C';
local $ENV{LANG} = 'C';
capture('git', 'status', '--porcelain') eq '' or die "dirty benchmark source\n";
my %hashes = map {$_ => sha256_hex(contents($_))} ($old, $binary, $worker, 'perl/lib/Wump.pm', 'perl/core/wump_core.c', 'perl/yield.pl');
my $cpu = contents('/proc/cpuinfo'); $cpu =~ /^model name\s*:\s*(.+)$/m or die;
my $cpu_model = $1;
my $kernel = capture('uname', '-srmo'); chomp $kernel;
my %binaries;
for my $spec ([before => $old], [after => $binary]) {
	my ($role, $path) = @$spec;
	my $config = capture($path, '-I' . dirname($path) . '/lib', '-MConfig', '-MJSON::PP', '-e',
		q{print JSON::PP::encode_json({map {$_ => $Config::Config{$_} // ''} qw(version archname cc gccversion ccflags ldflags lddlflags optimize usemultiplicity useithreads use64bitall)})});
	$binaries{$role} = {path => abs_path($path), sha256 => $hashes{$path}, config => JSON::PP::decode_json($config)};
}
my $sequence = 0;
for my $run (1..7) {
	for my $op ('yield') {
		my $n = 2000000;
		my @modes = qw(before after);
		for my $slots (1,2,4) {
			local $ENV{WUMPPROCS} = $slots;
			for my $offset (0..$#modes) {
				my $role = $modes[($offset + $run - 1) % @modes];
				my $mode = 'native';
				my $path = $binaries{$role}{path};
				my $started = clock_gettime(CLOCK_MONOTONIC);
				my $text = capture('taskset', '-c', '0,2,4,6', 'timeout', '90s', $path,
					'-I' . dirname($path) . '/lib', '-Iperl/lib', $worker, $op, $mode, $n);
				my $elapsed = clock_gettime(CLOCK_MONOTONIC) - $started;
				my $value = JSON::PP::decode_json($text);
				$value->{completed} == $n && $value->{iterations} == $n
					&& $value->{operation} eq $op && $value->{mode} eq $mode
					&& $value->{slots} == $slots && $value->{wall_seconds} > 0
					&& $value->{wall_seconds} <= $elapsed or die "bad result\n";
				print JSON::PP->new->canonical->encode({%$value, role => $role, run => $run,
					sequence => ++$sequence, process_seconds => $elapsed}), "\n";
			}
		}
	}
}
for my $path (keys %hashes) { sha256_hex(contents($path)) eq $hashes{$path} or die "changed file: $path\n" }
capture('git', 'status', '--porcelain') eq '' or die "source changed during measurement\n";
open my $out, '>', "$metadata_path.tmp" or die $!;
print {$out} JSON::PP->new->canonical->pretty->encode({
	source_revision => $revision, source_dirty => JSON::PP::false, binaries => \%binaries,
	sha256 => \%hashes,
	cpu_model => $cpu_model, kernel => $kernel, affinity => '0,2,4,6',
	runs => 7, iterations => 2000000, samples => $sequence,
	runner_source => contents(__FILE__),
}) or die $!;
close $out or die $!;
rename "$metadata_path.tmp", $metadata_path or die $!;
